import { FC } from 'react';

import { useIsAnyLoading } from 'pages/pillars/ValueCreation/VolumePages/contexts';
import { useExportSummaryPageHeader } from 'pages/pillars/ValueCreation/VolumePages/tabs/Summary/components/ExportSummaryPageHeader/hooks/useExportSummaryPageHeader';
import { ExportSummaryPageHeaderProps } from 'pages/pillars/ValueCreation/VolumePages/tabs/Summary/components/ExportSummaryPageHeader/types';
import {
  StyledExportButton,
  StyledExportIcon,
  StyledExportPageHeader,
} from 'shared/Styles/exportPages.styles';

const ExportIcon: FC = () => <StyledExportIcon />;

export const ExportSummaryPageHeader: FC<ExportSummaryPageHeaderProps> = ({
  dataTestId,
  monthYear,
}) => {
  const isAnyLoading = useIsAnyLoading();
  const { handlePDFExport } = useExportSummaryPageHeader({ monthYear });

  return (
    <StyledExportPageHeader
      data-testid={
        dataTestId
          ? `tabpanel-summary-export-page-header-${dataTestId}`
          : undefined
      }
    >
      <StyledExportButton
        data-testid={
          dataTestId
            ? `tabpanel-summary-refresh-button-${dataTestId}`
            : undefined
        }
        variant="primary"
        size="medium"
        onClick={handlePDFExport}
        isLoading={isAnyLoading}
        icon={ExportIcon}
        trailing
      >
        Export File
      </StyledExportButton>
    </StyledExportPageHeader>
  );
};
